// 8 control points defining a closed, gently curving track.
const TRACK_POINTS = [
  new THREE.Vector3(0, 0, 0),
  new THREE.Vector3(6, 0, -2),
  new THREE.Vector3(12, 0, 0),
  new THREE.Vector3(15, 0, 5),
  new THREE.Vector3(12, 0, 10),
  new THREE.Vector3(6, 0, 11),
  new THREE.Vector3(1, 0, 9),
  new THREE.Vector3(-3, 0, 4),
];

export function buildTrack() {
  const curve = new THREE.CatmullRomCurve3(TRACK_POINTS, true, 'centripetal');

  // Arc-length lookup table: cumulative lengths at N+1 uniformly spaced u samples.
  const LOOKUP_SIZE = 2048;
  const cumLen = new Float64Array(LOOKUP_SIZE + 1);
  const seg = new THREE.Vector3();
  let prev = curve.getPoint(0);
  for (let i = 1; i <= LOOKUP_SIZE; i++) {
    const u = i / LOOKUP_SIZE;
    const p = curve.getPoint(u);
    cumLen[i] = cumLen[i - 1] + prev.distanceTo(p);
    prev = p;
  }
  const totalLength = cumLen[LOOKUP_SIZE];

  // Map arc distance d (wrapped into [0, totalLength)) to curve parameter u
  // via binary search over the cumulative-length table plus linear interpolation.
  function uAtDistance(d) {
    let dist = d % totalLength;
    if (dist < 0) dist += totalLength;

    // Binary search: largest i with cumLen[i] <= dist.
    let lo = 0;
    let hi = LOOKUP_SIZE;
    while (lo < hi) {
      const mid = (lo + hi + 1) >> 1;
      if (cumLen[mid] <= dist) lo = mid;
      else hi = mid - 1;
    }

    const span = cumLen[lo + 1] - cumLen[lo];
    const t = span > 0 ? (dist - cumLen[lo]) / span : 0;
    return Math.min((lo + t) / LOOKUP_SIZE, 1);
  }

  return { curve, totalLength, uAtDistance };
}

const _pos = new THREE.Vector3();
const _tangent = new THREE.Vector3();

export function placeTrain(track, cars = 4, coupler = 1.5, headDistance = 0) {
  const { curve, totalLength, uAtDistance } = track;
  const placed = [];
  for (let i = 0; i < cars; i++) {
    // Car centers sit at arc distances headDistance - i*coupler (wrapped).
    const d = headDistance - i * coupler;
    const u = uAtDistance(d);
    const pos = curve.getPoint(u).clone();
    const tangent = curve.getTangent(u).clone().normalize();
    const forward = new THREE.Vector3().copy(tangent).normalize();
    const quaternion = new THREE.Quaternion().setFromUnitVectors(
      new THREE.Vector3(0, 0, 1),
      forward
    );
    placed.push({
      index: i,
      u,
      position: pos,
      forward,
      quaternion,
      arcDistance: ((d % totalLength) + totalLength) % totalLength,
    });
  }
  return placed;
}

export function stepTrain(state, speed, dt, track) {
  return placeTrain(track, state.length, state.length ? arguments[3] : undefined, 0), null;
}
