result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test/train.test.js", "content": "import { describe, it, expect } from 'vitest';
import { buildTrack, placeTrain, stepTrain } from '../src/train.js';

describe('train on curved track', () => {
  const track = buildTrack();

  it('arc gap between consecutive cars is exactly coupler (within 1e-9)', () => {
    const coupler = 1.5;
    const train = placeTrain(track, 4, coupler, 0);
    for (let i = 1; i < train.cars.length; i++) {
      const ahead = train.cars[i - 1].arcDistance;
      const behind = train.cars[i].arcDistance;
      // wrapped arc distance from car i to car i-1
      let gap = behind - ahead;
      if (gap < 0) gap += track.totalLength;
      expect(Math.abs(gap - coupler)).toBeLessThanOrEqual(1e-9);
    }
  });

  it('straight-line distance between consecutive centers is within 5% of coupler on gentle sections', () => {
    const coupler = 1.5;
    const train = placeTrain(track, 8, coupler, track.totalLength * 0.25);
    for (let i = 1; i < train.cars.length; i++) {
      const d = train.cars[i - 1].position.distanceTo(train.cars[i].position);
      // Chord <= arc always holds; allow up to 5% shrink tolerance.
      expect(d).toBeGreaterThan(coupler * 0.95);
      expect(d).toBeLessThanOrEqual(coupler + 1e-6);
    }
  });

  it('chord length never exceeds coupler + 1e-6', () => {
    const coupler = 1.5;
    for (let h = 0; h < 20; h++) {
      const train = placeTrain(track, 4, coupler, (h / 20) * track.totalLength);
      for (let i = 1; i < train.cars.length; i++) {
        const d = train.cars[i - 1].position.distanceTo(train.cars[i].position);
        expect(d).toBeLessThanOrEqual(coupler + 1e-6);
      }
    }
  });

  it('uAtDistance(totalLength) wraps to uAtDistance(0) within 1e-6', () => {
    const uEnd = track.uAtDistance(track.totalLength);
    const uStart = track.uAtDistance(0);
    expect(Math.abs(uEnd - uStart)).toBeLessThanOrEqual(1e-6);
    // Also negative and multi-wrap distances land in [0, 1).
    const u = track.uAtDistance(-3.7 * track.totalLength);
    expect(u).toBeGreaterThanOrEqual(0);
    expect(u).toBeLessThan(1);
  });

  it('stepping a full lap returns car 0 to its start within 1e-3', () => {
    const speed = 2.5;
    let state = placeTrain(track, 4, 1.5, 0);
    const startPos = state.cars[0].position.clone();
    const lapTime = track.totalLength / speed;
    // Step in fixed slices so we actually exercise repeated stepping.
    const steps = 64;
    for (let s = 0; s < steps; s++) {
      state = stepTrain(track, state, speed, lapTime / steps);
    }
    const endPos = state.cars[0].position;
    expect(startPos.distanceTo(endPos)).toBeLessThanOrEqual(1e-3);
  });

  it('forward vectors are unit length', () => {
    const train = placeTrain(track, 6, 1.5, track.totalLength / 3);
    for (const car of train.cars) {
      expect(Math.abs(car.forward.length() - 1)).toBeLessThanOrEqual(1e-9);
    }
  });
});
"})
